  ('4ff1b27f-84c2-43c6-85e2-17e951df68f2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ऐसी एक घटना का ज़िक्र सिंधी भाषा के महाकवि शेख अयाज़ ने अपनी आत्मकथा में किया है। उन्होंने लिखा है—'एक दिन उनके पिता कुएँ से नहाकर लौटे। माँ ने भोजन परोसा। उन्होंने जैसे ही रोटी का कौर तोड़ा। उनकी नज़र अपनी बाजू पर पड़ी। वहाँ एक काला च्योंटा रेंग रहा था। वह भोजन छोड़कर उठ खड़े हुए।' माँ ने पूछा, 'क्या बात है? भोजन अच्छा नहीं लगा?' शेख अयाज़ के पिता बोले, 'नहीं, यह बात नहीं है। मैंने एक घर वाले को बेघर कर दिया है। उस बेघर को कुएँ पर उसके घर छोड़ने जा रहा हूँ।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fa7f6190-17d3-47e0-8082-dbc9286dd986', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बाइबिल और दूसरे पावन ग्रंथों में नूह नाम के एक पैगंबर का ज़िक्र मिलता है। उनका असली नाम लश्कर था, लेकिन अरब ने उनको नूह के लकब से याद किया है। वह इसलिए कि आप सारी उम्र रोते रहे। इसका कारण एक ज़ख्मी कुत्ता था। नूह के सामने से एक बार एक घायल कुत्ता गुज़रा। नूह ने उसे दुत्कारते हुए कहा, 'दूर हो जा गंदे कुत्ते!' इस्लाम में कुत्तों को गंदा समझा जाता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6c5586fe-b9dd-49b0-bbb6-0f8f6e11f87d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुत्ते ने उनकी दुत्कार सुनकर जवाब दिया---'न मैं अपनी मर्ज़ी से कुत्ता हूँ, न तुम अपनी पसंद से इंसान हो। बनाने वाला सबका तो वही एक है।' नूह ने जब उसकी बात सुनी और दुखी हो मुद्दत तक रोते रहे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
