  ('479ff7a5-8019-4da8-a3c9-47c8c5c6c232', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दुनिया कैसे वजूद में आई? पहले क्या थी? किस बिंदु से इसकी यात्रा शुरू हुई? इन प्रश्नों के उत्तर विज्ञान अपनी तरह से देता है, धार्मिक ग्रंथ अपनी-अपनी तरह से।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4fd80cfb-411f-4911-a126-7ee93c440edf', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुछ साल पहले बम्बई (मुंबई) में देखने को मिला था और यह नमूना इतना डरावना था कि बम्बई निवासी डरकर अपने-अपने पूजा-स्थल में अपने खुदाओं से प्रार्थना करने लगे थे। कई सालों से बड़े-बड़े बिल्डर समंदर को पीछे धकेल कर उसकी ज़मीन को हथिया रहे थे। बेचारा समंदर लगातार सिमटता जा रहा था। पहले उसने अपनी फैली हुई टाँगें समेटीं, थोड़ा सिमटकर बैठ गया। फिर जगह कम पड़ी तो उकड़ूँ बैठ गया। फिर खड़ा हो गया---जब खड़े रहने की जगह कम पड़ी तो उसे गुस्सा आ गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('2794d0d2-e744-4a3e-9c36-f0ed9f8edd1d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जो जितना बड़ा होता है उसे उतना ही कम गुस्सा आता है। परंतु आता है तो रोकना मुश्किल हो जाता है, और यही हुआ, उसने एक रात अपनी लहरों पर दौड़ते हुए तीन जहाजों को उठाकर बच्चों की गेंद की तरह तीन दिशाओं में फेंक दिया। एक वली के समंदर के किनारे पर आकर गिरा, दूसरा बांद्रा में कार्टर रोड के सामने औंधे मुँह और तीसरा गेट-वे-ऑफ-इंडिया पर टूट-फूटकर सैलानियों का नज़ारा बना बावजूद कोशिश, वे फिर से चलने-फिरने के काबिल नहीं हो सके।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('62388807-49b2-4366-94b0-0646c472571d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरी माँ कहती थी, सूरज ढले आँगन के पेड़ों से पत्ते मत तोड़ो, पेड़ रोएँगे। दीया-बत्ती के वक्त फूलों को मत तोड़ो, फूल बद्दुआ देते हैं।--- दरिया पर जाओ तो उसे सलाम किया करो, वह खुश होता है। कबूतरों को मत सताया करो, वे हज़रत मुहम्मद को अज़ीज़ हैं। उन्होंने उन्हें अपनी मज़ार के नीले गुंबद पर घोंसले बनाने की इजाज़त दे रखी है। मुर्गे को परेशान नहीं किया करो, वह मुल्ला जी से पहले मोहल्ले में अज़ान देकर सबको सवेरे जगाता हैµ सब की पूजा एक-सी, अलग-अलग है रीत। मस्जिद जाए मौलवी, कोयल गाए गीत।।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('5345047e-8936-4929-a6c2-8bd661cbfb63', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ग्वालियर में हमारा एक मकान था, उस मकान के दालान में दो रोशनदान थे। उसमें कबूतर के एक जोड़े ने घोंसला बना लिया था। एक बार बिल्ली ने उछककर दो में से एक अंडा तोड़ दिया। मेरी माँ ने देखा तो उसे दुख हुआ। उसने स्टूल पर चढ़कर दूसरे अंडे को बचाने की कोशिश की। लेकिन इस कोशिश में दूसरा अंडा उसी के हाथ से गिरकर टूट गया। कबूतर परेशानी में इधर-उधर फड़फड़ा रहे थे। उनकी आँखों में दुख देखकर मेरी माँ की आँखों में आँसू आ गए। इस गुनाह को खुदा से मुआफ़ कराने के लिए उसने पूरे दिन रोज़ा रखा। दिन-भर कुछ खाया-पिया नहीं। सिर्फ रोती रही और बार-बार नमाज़ पढ़-पढ़कर खुदा से इस गलती को मुआफ़ करने की दुआ मांगती रही।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('d99426b5-087d-407c-a9eb-de1d8486411c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ग्वालियर से बम्बई की दूरी ने संसार को काफ़ी कुछ बदल दिया है। वर्सोवा में जहाँ आज मेरा घर है, पहले यहाँ दूर तक जंगल था। पेड़ थे, परिंदे थे और दूसरे जानवर थे। अब यहाँ समंदर के किनारे लंबी-चौड़ी बस्ती बन गई है। इस बस्ती ने न जाने कितने परिंदों-चरिंदों से उनका घर छीन लिया है। इनमें से कुछ शहर छोड़कर चले गए हैं। जो नहीं जा सके हैं उन्होंने यहाँ-वहाँ डेरा डाल लिया है। इनमें से दो कबूतरों ने मेरे फ्लैट के एक मचान में घोंसला बना लिया है। बच्चे अभी छोटे$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('caf26340-d208-4a55-a193-fba37bd8367a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनके खिलाने-पिलाने की ज़िम्मेदारी अभी बड़े कबूतरों की है। वे दिन में कई-कई बार आते-जाते हैं। और क्यों न आएँ-जाएँ आखिर उनका भी घर है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('41e67f6b-fb30-470f-afe3-963340122d89', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन उनके आने-जाने से हमें परेशानी भी होती है। वे कभी किसी चीज़ को गिराकर तोड़ देते हैं। कभी मेरी लाइब्रेरी में घुसकर कबीर या मिर्ज़ा ग़ालिब को सताने लगते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('34063594-fbca-4fc1-9484-e07b39f7d683', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस रोज़-रोज़ की परेशानी से तंग आकर मेरी पत्नी ने उस जगह जहाँ उनका आशियाना था, एक जाली लगा दी है, उनके बच्चों को दूसरी जगह कर दिया है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
