  ('084c2eb3-7586-4a71-9d7c-9d332f001cfe', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक दफा सुलेमान अपने लश्कर के साथ एक रास्ते से गुजर रहे थे। रास्ते में कुछ चींटियों ने घोड़ों की टापों की आवाज सुनी तो डर कर एक-दूसरे से कहा, 'आप जल्दी से अपने-अपने बिलों में चलो, फौज आ रही है।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('18b65a42-587a-41db-a2a8-5bc38d621b97', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुलेमान उनकी बातें सुनकर थोड़ी दूर पर रुक गए और चींटियों से बोले, 'घबराओ नहीं, सुलेमान को खुदा ने सबका रखवाला बनाया है। मैं किसी के लिए मुसीबत नहीं हूँ, सबके लिए मुहब्बत हूँ।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ba4bf392-3efd-4140-8fa5-ce030b3bf532', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$चींटियों ने उनके लिए ईश्वर से दुआ की और सुलेमान अपनी मंजिल की ओर बढ़ गए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('7b91824c-76d1-433c-9260-c1b6bbcc2519', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ऐसी एक घटना का ज़िक्र सिंधी भाषा के महाकवि शेख अयाज़ ने अपनी आत्मकथा में किया है। उन्होंने लिखा है—'एक दिन उनके पिता कुएँ से नहाकर लौटे। माँ ने भोजन परोसा। उन्होंने जैसे ही रोटी का कौर तोड़ा। उनकी नज़र अपनी बाजू पर पड़ी। वहाँ एक काला च्योंटा रेंग रहा था। वह भोजन छोड़कर उठ खड़े हुए।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('90136065-1634-41d8-90c1-06976d340c66', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$माँ ने पूछा, 'क्या बात है? भोजन अच्छा नहीं लगा?' शेख अयाज़ के पिता बोले, 'नहीं, यह बात नहीं है। मैंने एक घर वाले को बेघर कर दिया है। उस बेघर को कुएँ पर उसके घर छोड़ने जा रहा हूँ।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('382d371c-f41b-4156-9466-68ae380f9f7d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बाइबिल और दूसरे पावन ग्रंथों में नूह नाम के एक पैगंबर का ज़िक्र मिलता है। उनका असली नाम लश्कर था, लेकिन अरब ने उनको नूह के लकब से याद किया है। वह इसलिए कि आप सारी उम्र रोते रहे। इसका कारण एक ज़ख्मी कुत्ता था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b39787db-f6c8-4a39-aeaa-16e321c302eb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नूह के सामने से एक बार एक घायल कुत्ता गुज़रा। नूह ने उसे दुत्कारते हुए कहा, 'दूर हो जा गंदे कुत्ते!' इस्लाम में कुत्तों को गंदा समझा जाता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7495546f-e9b7-4d89-99e3-f82f3a26513c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुत्ते ने उनकी दुत्कार सुनकर जवाब दिया---'न मैं अपनी मर्ज़ी से कुत्ता हूँ, न तुम अपनी पसंद से इंसान हो। बनाने वाला सबका तो वही एक है।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3f816cca-df13-4f8b-a7c3-32ab8f9bab08', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मट्टी से मट्टी मिले, खो सभी निशान। किसमें कितना कौन है, कैसे हो पहचान।।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6cc2df1a-3c20-40b5-a06f-53563c174368', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नूह ने जब उसकी बात सुनी और दुखी हो मुद्दत तक रोते रहे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ca1278d1-77f2-4326-97e2-30c4cbfd154e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$महाभारत में युधिष्ठिर का जो अंत तक साथ निभाता नज़र आता है, वह भी प्रतीकात्मक रूप में एक कुत्ता ही था। सब साथ छोड़ते गए तो केवल वही उनके एकांत को शांत कर रहा था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('920767e1-a9f6-453c-93eb-3b4d4865a4eb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दुनिया कैसे वजूद में आई? पहले क्या थी? किस बिंदु से इसकी यात्रा शुरू हुई? इन प्रश्नों के उत्तर विज्ञान अपनी तरह से देता है, धार्मिक ग्रंथ अपनी-अपनी तरह से।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d3ed2169-6056-4f30-bda5-1f89a997e6ba', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$संसार की रचना भले ही कैसे हुई हो लेकिन धरती किसी एक की नहीं है। पंछी, मानव, पशु, नदी, पर्वत, समंदर आदि की इसमें बराबर की हिस्सेदारी है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b7057604-bed1-435d-bbb3-f9c6692a42ae', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह और बात है कि इस हिस्सेदारी में मानव जाति ने अपनी बुद्धि से बड़ी-बड़ी दीवारें खड़ी कर दी हैं। पहले पूरा संसार एक परिवार के समान था अब टुकड़ों में बँटकर एक-दूसरे से दूर हो चुका है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8b6e55fb-ea6c-49ec-a29b-de381afea2d3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पहले बड़े-बड़े दालानों-आँगनों में सब मिल-जुलकर रहते थे अब छोटे-छोटे डिब्बे जैसे घरों में जीवन सिमटने लगा है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4cf8aeb7-e705-4c36-9405-7dbb505ad483', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बढ़ती हुई आबादियों ने समंदर को पीछे सरकाना शुरू कर दिया है, पेड़ों को रास्तों से हटाना शुरू कर दिया है, फैलते हुए प्रदूषण ने पंछियों को बस्तियों से भगाना शुरू कर दिया है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('92e81c91-2915-479b-9c95-782e08c8670e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बारूदों की विनाशलीलाओं ने वातावरण को सताना शुरू कर दिया। अब गर्मी में ज़्यादा गर्मी, बेवक्त की बरसातें, ज़लज़ले, सैलाब, तूफ़ान और नित नए रोग, मानव और प्रकृति के इसी असंतुलन के परिणाम हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('74496d7f-d335-40aa-9b3e-f939dc7643a8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नेचर की सहनशक्ति की एक सीमा होती है। नेचर के गुस्से का एक नमूना$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c262cf4d-87aa-4e1a-9399-53c485d3ae63', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सिंधी भाषा के महाकवि शेख अयाज़ ने अपनी आत्मकथा में एक घटना का ज़िक्र किया है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a70fa100-9983-48e9-8199-9674ba8982be', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन्होंने लिखा है—'एक दिन उनके पिता कुएँ से नहाकर लौटे। माँ ने भोजन परोसा।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('561dd699-76e0-4e98-8f2f-23231a691343', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन्होंने जैसे ही रोटी का कौर तोड़ा। उनकी नज़र अपनी बाजू पर पड़ी। वहाँ एक काला च्योंटा रेंग रहा था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c8a4fa65-27ba-44fa-a0fc-2f8a58e44763', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह भोजन छोड़कर उठ खड़े हुए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b00e2745-d77a-4321-b9a9-a64121e5fba2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नूह नाम के एक पैगंबर का ज़िक्र मिलता है। उनका असली नाम लश्कर था, लेकिन अरब ने उनको नूह के लकब से याद किया है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3ea5f2f7-1fe2-4290-85b8-13e91f748629', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह इसलिए कि आप सारी उम्र रोते रहे। इसका कारण एक ज़ख्मी कुत्ता था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('33d85e87-25ca-4d51-aed5-384695ccf4cc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नूह के सामने से एक बार एक घायल कुत्ता गुज़रा। नूह ने उसे दुत्कारते हुए कहा, 'दूर हो जा गंदे कुत्ते!'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0ba6b905-4a24-461d-9d49-ea5584e3fe16', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मानव जाति ने अपनी बुद्धि से बड़ी-बड़ी दीवारें खड़ी कर दी हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a1a41e62-5030-43ce-988b-00b523aefc8e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पहले पूरा संसार एक परिवार के समान था अब टुकड़ों में बँटकर एक-दूसरे से दूर हो चुका है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('11985b77-6bfb-4dad-9e80-10f81f2d6723', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फैलते हुए प्रदूषण ने पंछियों को बस्तियों से भगाना शुरू कर दिया है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ca616b5f-4d62-4b48-a96f-3d637a715c83', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुछ साल पहले बम्बई (मुंबई) में देखने को मिला था और यह नमूना इतना डरावना था कि बम्बई निवासी डरकर अपने-अपने पूजा-स्थल में अपने खुदाओं से प्रार्थना करने लगे थे। कई सालों से बड़े-बड़े बिल्डर समंदर को पीछे धकेल कर उसकी ज़मीन को हथिया रहे थे। बेचारा समंदर लगातार सिमटता जा रहा था। पहले उसने अपनी फैली हुई टाँगें समेटीं, थोड़ा सिमटकर बैठ गया। फिर जगह कम पड़ी तो उकड़ूँ बैठ गया। फिर खड़ा हो गया---जब खड़े रहने की जगह कम पड़ी तो उसे गुस्सा आ गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('434a31db-70d5-41a0-9bb6-dbf189f5df53', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जो जितना बड़ा होता है उसे उतना ही कम गुस्सा आता है। परंतु आता है तो रोकना मुश्किल हो जाता है, और यही हुआ, उसने एक रात अपनी लहरों पर दौड़ते हुए तीन जहाजों को उठाकर बच्चों की गेंद की तरह तीन दिशाओं में फेंक दिया। एक वली के समंदर के किनारे पर आकर गिरा, दूसरा बांद्रा में कार्टर रोड के सामने औंधे मुँह और तीसरा गेट-वे-ऑफ-इंडिया पर टूट-फूटकर सैलानियों का नज़ारा बना बावजूद कोशिश, वे फिर से चलने-फिरने के काबिल नहीं हो सके।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('cb543fa8-0e07-4ba1-aced-4434d6c8643e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरी माँ कहती थी, सूरज ढले आँगन के पेड़ों से पत्ते मत तोड़ो, पेड़ रोएँगे। दीया-बत्ती के वक्त फूलों को मत तोड़ो, फूल बद्दुआ देते हैं।--- दरिया पर जाओ तो उसे सलाम किया करो, वह खुश होता है। कबूतरों को मत सताया करो, वे हज़रत मुहम्मद को अज़ीज़ हैं। उन्होंने उन्हें अपनी मज़ार के नीले गुंबद पर घोंसले बनाने की इजाज़त दे रखी है। मुर्गे को परेशान नहीं किया करो, वह मुल्ला जी से पहले मोहल्ले में अज़ान देकर सबको सवेरे जगाता हैµ सब की पूजा एक-सी, अलग-अलग है रीत। मस्जिद जाए मौलवी, कोयल गाए गीत।।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('891d7329-fd85-453b-8124-9992be29b2d3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ग्वालियर में हमारा एक मकान था, उस मकान के दालान में दो रोशनदान थे। उसमें कबूतर के एक जोड़े ने घोंसला बना लिया था। एक बार बिल्ली ने उछककर दो में से एक अंडा तोड़ दिया। मेरी माँ ने देखा तो उसे दुख हुआ। उसने स्टूल पर चढ़कर दूसरे अंडे को बचाने की कोशिश की। लेकिन इस कोशिश में दूसरा अंडा उसी के हाथ से गिरकर टूट गया। कबूतर परेशानी में इधर-उधर फड़फड़ा रहे थे। उनकी आँखों में दुख देखकर मेरी माँ की आँखों में आँसू आ गए। इस गुनाह को खुदा से मुआफ़ कराने के लिए उसने पूरे दिन रोज़ा रखा। दिन-भर कुछ खाया-पिया नहीं। सिर्फ रोती रही और बार-बार नमाज़ पढ़-पढ़कर खुदा से इस गलती को मुआफ़ करने की दुआ मांगती रही।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('25bacbc6-6c27-480d-9be2-c9da1b0dff2c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9febfa65-e1e2-4bd8-8395-6e3af95511a6', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ग्वालियर से बम्बई की दूरी ने संसार को काफ़ी कुछ बदल दिया है। वर्सोवा में जहाँ आज मेरा घर है, पहले यहाँ दूर तक जंगल था। पेड़ थे, परिंदे थे और दूसरे जानवर थे। अब यहाँ समंदर के किनारे लंबी-चौड़ी बस्ती बन गई है। इस बस्ती ने न जाने कितने परिंदों-चरिंदों से उनका घर छीन लिया है। इनमें से कुछ शहर छोड़कर चले गए हैं। जो नहीं जा सके हैं उन्होंने यहाँ-वहाँ डेरा डाल लिया है। इनमें से दो कबूतरों ने मेरे फ्लैट के एक मचान में घोंसला बना लिया है। बच्चे अभी छोटे$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-969Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
